{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver approaches the ruined city gates.",
      "visual_description": "The glass diver stands before the massive iron gates of a ruined royal city, his diving helmet reflecting the broken spires and torn banners beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unfolds a worn map.",
      "visual_description": "Mara the cartographer sits on a fallen pillar, ink-stained coat flapping, pointing at a faded map as the oracle lamp glows beside her.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The oracle lamp's single eye flickers as it casts a dancing shadow of a crooked tower on a broken wall.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts through a narrow alley.",
      "visual_description": "The tin fox, key-wind tail ticking, peers around a corner into a courtyard filled with old royal banners hanging limp.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "They encounter the sleeping tax collector at a checkpoint.",
      "visual_description": "The sleeping tax collector snores on a stack of ledgers, stamped papers stuck to his sleeves, blocking a passage under a crumbling arch.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver swims through a window into a locked chamber.",
      "visual_description": "The glass diver's form ripples as he passes through a stained-glass window into a dark room, his helmet glowing faintly.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Mara reads a secret path from her compass.",
      "visual_description": "Mara the cartographer holds her brass compass high, its needle spinning before pointing toward a hidden door in a wall of vines.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp warns of a trap on the stairs.",
      "visual_description": "The oracle lamp's flame turns blue, casting an eerie light on a staircase where loose stones seem ready to collapse.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "The sleeping tax collector wakes briefly and stamps a useless permit.",
      "visual_description": "The sleeping tax collector opens one eye, stamps a piece of paper with a flourish, then instantly falls back asleep on his ledger pillow.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "They pass through a magic door that whispers old city secrets.",
      "visual_description": "A stone door carved with runes swings open silently, revealing a corridor where ghostly whispers echo from the walls.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The tin fox disarms a pressure plate trap.",
      "visual_description": "The tin fox's small metal claws carefully lift a tile, revealing a hidden mechanism that clicks to a halt.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara sketches the route to the tower's heart.",
      "visual_description": "Mara the cartographer quickly draws on a scrap of parchment, her ink-stained fingers tracing a path around a fountain shaped like a coiled serpent.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver peers through a mirror into the rescue target's cell.",
      "visual_description": "The glass diver presses his helmet against a large, dusty mirror, seeing a figure huddled in a small, barred chamber on the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector is left behind as they ascend the tower.",
      "visual_description": "The sleeping tax collector remains snoring on his ledger pile while the others climb a spiral staircase, his stamped papers fluttering in the draft.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The oracle lamp's flame dims near the top of the tower.",
      "visual_description": "The oracle lamp's eye grows faint, its flame almost going out as they approach a door covered in frost.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "They unlock the cell using the glass diver's reflected light.",
      "visual_description": "The glass diver angles his helmet to catch a beam of moonlight, focusing it onto a keyhole that clicks open.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The rescued figure is led down the tower as it begins to crumble.",
      "visual_description": "The glass diver and Mara help a cloaked figure down the shaking staircase, stones falling around them as the tin fox scampers ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The team escapes across a crumbling bridge at dawn.",
      "visual_description": "The entire group races across a narrow stone bridge, the city collapsing behind them, the oracle lamp's flame bright and steady again against the sunrise.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

